import type { LearningTask } from "../../lib/content/cisco-learning.ts";

// Authored cases, not pretend device configurations. A supplied case observation is never runtime evidence.
type Case = {
  id: string; stage: string; title: string; previous: string; minutes: number; type?: string;
  diagram: string; state: string; goal: string; action: string[]; why: string;
  checks: string[]; fault: string; repair: string; solution: string;
  questions: [string, string][]; skills: string[]; sources: string[];
};
function guided(c: Case): LearningTask {
  return {
    id: c.id, stageIds: [c.stage], titleFa: c.title, type: c.type ?? "guided-design", minutes: c.minutes,
    scenarioFa: `شرکت مدار: ${c.state}`, prerequisites: [c.previous], preLessonFa: c.why, topologyId: "guided-reference",
    referenceTopology: c.diagram,
    initialState: { afterTask: null, setup: [], descriptionFa: `${c.state} این دادهٔ مطالعهٔ موردی است؛ خروجی دستگاه زنده نیست.` },
    goalFa: c.goal,
    steps: c.action.map(instructionFa => ({ deviceId: "case-study", instructionFa, whyFa: c.why })),
    hintsFa: ["ابتدا پیش‌نیاز و مرز شبکه را از نقشه مشخص کن؛ حدس را جای شواهد نگذار.", c.checks[0], c.solution],
    verification: c.checks.map(expectedFa => ({ deviceId: "case-study", commands: [], expectedFa })),
    faults: [{ id: `${c.id}-fault`, descriptionFa: c.fault, commands: [], expectedFailureFa: "اثر خرابی را با هدف و معیارهای همین پرونده مقایسه کن؛ Pass اجرای دستگاه ادعا نمی‌شود.", repair: [], repairFa: c.repair }],
    solution: [], explanationFa: c.solution, assessment: "guided-knowledge",
    passCriteria: c.questions.map(([questionFa], i) => ({ id: `${c.id}-review-${i}`, assertionFa: questionFa })),
    reviewQuestions: c.questions.map(([questionFa, answerFa]) => ({ questionFa, answerFa })),
    skills: c.skills, sourceIds: c.sources,
    simulatorMapping: { targetDeviceIds: [], limitationFa: "این ویژگی در موتور فعلی اجرا نمی‌شود. نقشه و مشاهدات، مرجع آموزشی برچسب‌دارند. تیک این درس فقط پاسخ صحیح به بررسی فهم پرونده است؛ نه تأیید CLI، Packet، Policy، Appliance یا مهارت عملی آزمون. برای اثبات اجرای واقعی باید خروجی محیط پشتیبانی‌شده جدا بازبینی شود." },
  };
}

